<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$c = B::charge($id); if ($c === null) { http_response_code(404); echo V::empty('Cobrança não encontrada.'); return; } $open = !in_array($c['status'], ['paid', 'canceled'], true) && CmsAuth::can($admin, 'charges.manage'); ?>
<div class="cms-grid-2"><div><div class="cms-card"><h2><?= V::e($c['reference']) ?></h2><dl class="cms-dl"><dt>Assinante</dt><dd><a href="/assinaturas/<?= (int) $c['subscription_id'] ?>"><?= V::e($c['owner_name']) ?></a></dd><dt>Plano</dt><dd><?= V::e($c['plan_name']) ?></dd><dt>Valor</dt><dd><?= V::money($c['amount']) ?></dd><dt>Vencimento</dt><dd><?= V::date($c['due_date'], false) ?></dd><dt>Situação</dt><dd><?= V::badge($c['status'], V::CHARGE_STATUS[$c['status']] ?? $c['status']) ?></dd><dt>Pago em</dt><dd><?= V::date($c['paid_at']) ?></dd><dt>Comprovante</dt><dd><?= V::e($c['provider_reference'] ?? '—') ?></dd></dl></div>
<div class="cms-card"><h2>Tentativas</h2><?php $rows = B::attempts($id); if ($rows === []): ?><?= V::empty('Sem tentativas registradas.') ?><?php endif; foreach ($rows as $a): ?><p><small><?= V::date($a['created_at']) ?> · <?= V::e($a['outcome']) ?> · <?= V::e($a['note']) ?> · <?= V::e($a['actor_email'] ?? 'Sistema') ?></small></p><?php endforeach; ?></div></div>
<aside><?php if ($open): ?><form class="cms-card" method="post" action="/acao/charge-paid" data-confirm="Confirmar que este pagamento foi recebido?"><h2>Confirmar pagamento</h2><p><small>Use somente com o comprovante em mãos. Ativa a assinatura.</small></p><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Referência do comprovante', 'reference', '', ['required' => true]) ?><button class="cms-btn-primary">Confirmar</button></form>
<form class="cms-card" method="post" action="/acao/charge-failed"><h2>Registrar falha</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Motivo', 'note', '', ['required' => true]) ?><button class="cms-btn">Registrar</button></form><?php endif; ?></aside></div>
